// DECLARATIONS FOR THE `./recovery` ENTRY: the recovery file as it travels - the envelope a wallet writes and a
// sweep page reads back.
//
// src/public/recovery.mjs only NAMES what the engine already offers; these declarations NAME the same thing for a
// TypeScript consumer. Every signature is copied from the module the barrel re-exports
// (`engine/recovery/recoveryFile.js`, itself a generated byte-for-byte copy of the engine source), and a symbol
// the barrel does not re-export is not declared here.
//
// NO DOM AND NO ARGUMENTS: the module touches WebCrypto (`crypto.subtle`), `btoa`/`atob` and the text encoders,
// so the environment hands those in and nothing has to be passed as a parameter here.

/**
 * The envelope version (encryption) - NOT the payload version inside it. 1 is a file written without AAD, 2 is a
 * file whose header is authenticated. Both stay readable: people hold version-1 files, and a recovery file is the
 * only way to claim their XMR.
 */
export declare const ENVELOPE_VERSION: number;

/** The payload version (deal content), raised independently of the envelope: 1 keys as fields, 2 the mnemonic, 3 halves. */
export declare const PAYLOAD_VERSION: number;

/** The envelope version of a file written WITHOUT a passphrase: the payload travels in the clear and the header says so. */
export declare const UNENCRYPTED_ENVELOPE_VERSION: number;

/** The algorithm identifier of an unencrypted envelope. */
export declare const ALG_NONE: string;

/** The mark every Ninsei recovery file carries in its payload, so a foreign file is refused by name. */
export declare const FILE_MAGIC: string;

/** The deal fields of the envelope header that sit under authentication (`meta`). Each one is optional: a header without `meta` is still a header. */
export interface RecoveryEnvelopeMeta {
  /** The deal id the file belongs to. */
  readonly id?: string | null;
  /** The side of the deal the file was issued for. */
  readonly side?: string | null;
  /** When the file was written, as the deal record carries it. */
  readonly createdAt?: string | number | null;
  /** The order terms hash from the contract: the file's tie to the chain. */
  readonly termsHash?: string | null;
}

/** The envelope header BEFORE encryption: the same fields also form the AAD of the ciphertext, which is why the writer and the reader build them from one place. */
export interface RecoveryEnvelopeHeader {
  readonly v: number;
  /** The algorithm identifier: one string for the whole module. */
  readonly alg: string;
  /** The PBKDF2 iteration count, read FROM THE FILE on decryption so it can be raised without losing already issued files. */
  readonly iter: number;
  /** The PBKDF2 salt, base64. */
  readonly salt: string;
  /** The AES-GCM IV, base64. */
  readonly iv: string;
}

/** An encrypted recovery file object as it is written (`ninsei-<id>.json.enc`) and read back. */
export interface RecoveryEnvelope extends RecoveryEnvelopeHeader {
  /** The AES-GCM ciphertext of the payload, base64. */
  readonly ciphertext: string;
  /** The authenticated deal fields of the header. */
  readonly meta?: RecoveryEnvelopeMeta | null;
}

/** A recovery file written WITHOUT a passphrase: the payload is readable, the envelope says so, and no key is derived. */
export interface RecoveryPlainEnvelope {
  readonly v: number;
  readonly alg: string;
  readonly meta?: RecoveryEnvelopeMeta | null;
  readonly payload: RecoveryPayload;
}

/**
 * The AAD string: the header fields, in one FIXED order, that AES-GCM authenticates beside the ciphertext.
 *
 * Exported on purpose - the string is part of the format, so a check builds it with this same code instead of its
 * own copy. An absent `meta` contributes nulls; any edit to a header field changes the string and decryption is
 * refused.
 */
export declare function envelopeAad(envelope: RecoveryEnvelope): string;

/** The heights a recovery scan may start from. All three are optional; a source that did not answer is simply not a source. */
export interface RecoveryScanHeightRequest {
  /** The escrow's birth height, from the creation receipt. */
  readonly escrowBirthHeight?: string | number | null;
  /** The height the application stored when it registered the watch - the source that survives a deal record without one. */
  readonly serverRestoreHeight?: string | number | null;
  /** The Monero node's current height. */
  readonly nodeHeight?: string | number | null;
}

/**
 * The height to start the recovery scan from: the smallest KNOWN height, one block lower and never below 1, or null
 * when no source answered. A scan that starts below the money finds it; one that starts above never does.
 */
export declare function scanStartHeight(request?: RecoveryScanHeightRequest): number | null;

/** One side of the payment the payload carries. */
export interface RecoveryPayment {
  readonly token?: string | null;
  readonly amount?: string | number | null;
}

/** What the deal receives: XMR, at the address the file was issued for. */
export interface RecoveryReceive {
  readonly token?: string | null;
  readonly amount?: string | number | null;
  readonly address?: string | null;
}

/** The signed quote as the payload carries it: the signature, and the last eight characters of it as the nonce. */
export interface RecoveryQuote {
  readonly signature?: string | null;
  readonly nonce?: string | null;
}

/** The escrow of the deal, as the deal record carries it. Fields beyond these travel through unchanged. */
export interface RecoveryEscrow {
  readonly address?: string | null;
  readonly termsHash?: string | null;
  readonly [key: string]: unknown;
}

/** A wallet built from HALVES (payload v3): no full spend key exists for anyone, so there is no mnemonic here. */
export interface RecoveryWalletHalves {
  readonly source?: string | null;
  readonly library?: string | null;
  readonly network?: string | null;
  readonly address?: string | null;
  readonly subaddress?: string | null;
  /** MY half of the spend key. */
  readonly spendHalf?: string | null;
  /** MY half of the view key. */
  readonly viewHalf?: string | null;
  /** The counterparty's public spend point. */
  readonly otherSpendPoint?: string | null;
  /** The counterparty's public view point. */
  readonly otherViewPoint?: string | null;
  /** The counterparty's view HALF - not a secret: the full view key sees funds and cannot spend them. */
  readonly otherViewHalf?: string | null;
  /** The escrow address the revealed half is read from. */
  readonly escrowAddress?: string | null;
  readonly restoreHeight?: number | null;
}

/** A wallet built from a MNEMONIC (payload v1/v2): the phrase is the single source of both keys. */
export interface RecoveryWalletMnemonic {
  readonly source?: string | null;
  readonly library?: string | null;
  readonly network?: string | null;
  readonly address?: string | null;
  readonly subaddress?: string | null;
  readonly mnemonic?: string | null;
  readonly publicSpendKey?: string | null;
  readonly publicViewKey?: string | null;
  readonly restoreHeight?: number | null;
}

/** The Monero wallet data of the payload. Which shape it is follows the payload version. */
export type RecoveryWallet = RecoveryWalletHalves | RecoveryWalletMnemonic;

/**
 * The payload inside the ciphertext: everything needed to complete or roll back the deal without the site.
 *
 * The fields are OPTIONAL on purpose - a file issued earlier carries fewer of them and must still read, and an
 * unknown extra key is tolerated rather than refused. `magic`, `swapId`, `moneroWallet` and a supported `version`
 * are what validation requires, and it names the one that is missing.
 */
export interface RecoveryPayload {
  readonly magic?: string;
  readonly version?: number;
  readonly swapId?: string;
  readonly termsHash?: string | null;
  readonly side?: string | null;
  readonly network?: string | null;
  readonly moneroNetwork?: string | null;
  readonly createdAt?: string | number | null;
  readonly pay?: RecoveryPayment | null;
  readonly receive?: RecoveryReceive | null;
  readonly rate?: string | number | null;
  readonly maker?: string | null;
  readonly quote?: RecoveryQuote | null;
  readonly escrow?: RecoveryEscrow | null;
  readonly moneroWallet?: RecoveryWallet | null;
  /** The deal's timeline, taken from the record unchanged. */
  readonly deadlines?: unknown;
  readonly recoveryClient?: string;
  readonly [key: string]: unknown;
}

/** The deal record the payload is built from. Only the fields `buildPayload` reads are named here. */
export interface RecoverySwapRecord {
  readonly id: string;
  readonly side?: string | null;
  readonly network?: string | null;
  readonly moneroNetwork?: string | null;
  readonly createdAt?: string | number | null;
  readonly payToken?: string | null;
  readonly payAmount?: string | number | null;
  readonly xmrAmount?: string | number | null;
  readonly rate?: string | number | null;
  readonly maker?: string | null;
  readonly quoteSignature?: string | null;
  readonly escrow?: RecoveryEscrow | null;
  readonly timeline?: unknown;
  readonly [key: string]: unknown;
}

/** Everything `buildPayload` assembles the payload from. `escrow` is the sender's COPY, not necessarily the one on the deal. */
export interface RecoveryBuildRequest {
  readonly swap: RecoverySwapRecord;
  /** The wallet the file is issued for; without it no wallet block is written at all. */
  readonly swapWallet?: RecoveryWallet | null;
  readonly escrow?: RecoveryEscrow | null;
  readonly receiveAddress?: string | null;
  readonly restoreHeight?: number | null;
}

/**
 * The payload of one deal: the deal fields, the escrow, the wallet data and the deadlines.
 *
 * The version tells the truth about the CONTENT, not about the module: a halves wallet is 3 and a mnemonic wallet
 * is 2, whatever version this build happens to be.
 */
export declare function buildPayload(request: RecoveryBuildRequest): RecoveryPayload;

/** The verdict of a successful validation: the warnings a sweep page should show, each one naming what is missing. */
export interface RecoveryValidation {
  readonly warnings: readonly string[];
}

/**
 * Validates a payload AFTER decryption: garbage can decrypt too, so the magic, the version, the deal id and the
 * wallet fields are each checked, and a refusal throws with a clear cause - and never with a secret in its text.
 */
export declare function validatePayload(payload: RecoveryPayload): RecoveryValidation;

/**
 * Writes one payload into a recovery file envelope. A non-empty passphrase derives a key from a fresh salt and IV
 * and authenticates the header as AAD; a passphrase shorter than 12 characters is refused. An EMPTY passphrase
 * writes the payload in the clear, with the envelope naming that fact.
 */
export declare function encryptPayload(payload: RecoveryPayload, passphrase: string): Promise<RecoveryEnvelope | RecoveryPlainEnvelope>;

/** Whether the file asks for a passphrase. False for an unencrypted envelope. */
export declare function isEncrypted(fileObject: unknown): boolean;

/**
 * Decrypts a recovery file: the envelope version, the algorithm, the required fields and the iteration count are
 * checked BEFORE the key is derived, a version-1 file is read without AAD, and the payload is validated before it
 * is returned. A wrong password and an altered file are both named refusals, never a silent failure.
 */
export declare function decryptFile(fileObject: unknown, passphrase: string): Promise<RecoveryPayload>;

/** The whole file as TEXT, ready to be written: the envelope, pretty-printed, with BigInt key halves as hex strings. */
export declare function createRecoveryFile(payload: RecoveryPayload, passphrase: string): Promise<string>;

/**
 * The name the file is written under: lowercase, tied to the deal, `ninsei-pending.json.enc` while there is no id
 * yet. Stable, so a repeated download shows up as a second copy of one name rather than a new random file.
 */
export declare function recoveryFileName(swapId?: string | null): string;


// ---------------------------------------------------------------------------------------------------
// ONE RECOVERY KEY PER BROWSER (sdk#79)
// ---------------------------------------------------------------------------------------------------

/** The version of the stored/backup key record. */
export declare const RECOVERY_KEY_VERSION: number;
/** Twelve words, by the BIP39 rules. */
export declare const RECOVERY_KEY_WORDS: number;
/** The store key a browser adapter keeps the key under. */
export declare const RECOVERY_KEY_STORE: string;
/** The first line of a plain backup file. */
export declare const RECOVERY_KEY_FILE_MAGIC: string;
/** The domain half derivation binds to; the chain id and swap number join it. */
export declare const RECOVERY_KEY_DOMAIN: string;
/** The domain of the counterparty's view half, derived from the same one key. */
export declare const MAKER_VIEW_HALF_DOMAIN: string;
/** The encrypted backup envelope version. */
export declare const RECOVERY_KEY_ENVELOPE_VERSION: number;
/** The encrypted backup algorithm identifier. */
export declare const RECOVERY_KEY_ALG: string;
/** The PBKDF2 iteration count written into an encrypted backup. */
export declare const RECOVERY_KEY_ITER: number;

/** A key as it is kept: the words are the secret, the fingerprint is its short public name. */
export interface RecoveryKey {
  readonly version: number;
  readonly mnemonic: string;
  readonly fingerprint: string;
  readonly createdAt: string;
}

/** A derived swap number: the halves cross JSON as hex scalars. */
export interface TakerHalves {
  readonly index: number;
  readonly binding: string;
  readonly spendHalf: string;
  readonly viewHalf: string;
  readonly spendPoint: string;
  readonly viewPoint: string;
  readonly makerViewHalf: string;
  readonly makerViewPoint: string;
  readonly spendCommitment: string;
}

/** One order found by the key's commitments. */
export interface FoundSwap {
  readonly escrow: string;
  readonly locker: string;
  readonly claimer: string;
  readonly commitHalfLocker: string;
  readonly commitHalfClaimer: string;
  readonly edPointLocker: string;
  readonly edPointClaimer: string;
  readonly edViewPointLocker: string;
  readonly amount: string;
  readonly readyBy: number;
  readonly t1: number;
  readonly salt: string;
  readonly registry: string;
  readonly provider: string;
  readonly quoteKey: string;
  readonly transactionHash: string | null;
  readonly blockNumber: number | null;
  readonly logIndex: number | null;
  readonly index: number;
  readonly side: "locker" | "claimer";
  /** The Monero height a withdrawal may start from, derived from the order's block time. Null when the caller did
   * not pass the readers; `startHeightReason` then names why. */
  readonly startHeight: number | null;
  readonly startHeightReason: "no-block-number" | "no-height-readers" | "no-block-time" | "monero-header" | null;
}

/** A storage adapter: the same shape the SDK store takes. */
export interface RecoveryKeyStorage {
  get(key: string): string | null;
  set(key: string, value: string): unknown;
  remove(key: string): unknown;
}

/** Makes a new 12-word key. The caller saves it; nothing is stored here. */
export declare function createRecoveryKey(options?: { createdAt?: string | Date }): RecoveryKey;
/** Imports and validates words. */
export declare function importRecoveryKey(mnemonic: string, options?: { createdAt?: string | Date }): RecoveryKey;
/** The short public fingerprint (four hex characters) of the words. */
export declare function fingerprintOf(mnemonic: string): string;
/** The binding for a chain and swap number: `ninsei-taker-v1|<chainId>|<index>`. */
export declare function recoveryBinding(chainId: number, index: number): string;
/** Derives the taker spend and view halves for one swap number. */
export declare function takerHalves(request: { mnemonic: string; chainId: number; index: number }): TakerHalves;
/** The stable backup name, with `DO-NOT-DELETE` in it on purpose. */
export declare function recoveryKeyFileName(request: { mnemonic?: string; fingerprint?: string; createdAt?: string | Date }): string;
/** A plain backup file: readable header above the words. */
export declare function recoveryKeyText(request: { mnemonic: string; createdAt?: string | Date }): string;
/** A backup file, optionally encrypted with a passphrase of at least 12 characters. */
export declare function createRecoveryKeyFile(request: { mnemonic: string; createdAt?: string | Date; passphrase?: string }): Promise<string>;
/** Reads a plain or encrypted backup file and validates the words. */
export declare function openRecoveryKeyFile(contents: string, passphrase?: string): Promise<RecoveryKey>;
/** Saves the key through a storage adapter. */
export declare function saveRecoveryKey(storage: RecoveryKeyStorage, key: RecoveryKey & { nextIndex?: number; reserved?: Record<string, unknown>; retired?: Record<string, unknown> }): RecoveryKey;
/** Reads the key from a storage adapter, or null. */
export declare function loadRecoveryKey(storage: RecoveryKeyStorage): (RecoveryKey & { nextIndex: number; reserved: Record<string, unknown>; retired: Record<string, unknown> }) | null;
/** Reserves a swap number; the caller releases it if the request is abandoned. */
export declare function reserveRecoveryIndex(storage: RecoveryKeyStorage, request: { chainId: number; swapId?: string | null }): number;
/** Releases a number that never reached the chain. */
export declare function releaseRecoveryIndex(storage: RecoveryKeyStorage, index: number): void;
/** Retires a number after its order exists on chain. */
export declare function commitRecoveryIndex(storage: RecoveryKeyStorage, index: number): void;
/** Finds orders whose commitment was made from the key's halves. */
export declare function findSwaps(request: {
  mnemonic: string;
  chainId: number;
  factory: string;
  address?: string | null;
  evmLogs: (request: { address: string; topics: (string | null)[]; fromBlock: number | string; toBlock: number | string }) => Promise<unknown[]>;
  fromBlock?: number | string;
  toBlock?: number | string;
  gap?: number;
  maxIndex?: number;
  /** Reads the settlement block timestamp, in seconds: (blockNumber) -> seconds. */
  evmBlockTime?: (blockNumber: number) => Promise<number>;
  /** The Monero tip at the time of the search: () -> height. */
  moneroTip?: () => Promise<number>;
  /** A Monero block header timestamp, in seconds: (height) -> seconds. */
  moneroBlockTimestamp?: (height: number) => Promise<number>;
  /** Convenience: the node URLs the caller already probed. When the two Monero readers above are absent, the SDK
   * asks these for `get_info` and `get_block_header_by_height` itself. */
  xmrNodes?: readonly (string | { readonly url: string })[];
  /** The Monero network those nodes must name (mainnet, stagenet, testnet). */
  moneroNetwork?: string | null;
  /** The fetch used for those node requests; absent - the global fetch. */
  fetchImpl?: typeof fetch;
}): Promise<{ swaps: FoundSwap[]; scanned: number }>;
